let raw = (msg.payload || '').trim();

try {
    msg.payload = raw && raw !== '' ? JSON.parse(raw) : [];
} catch (e) {
    // Fallback: als json_agg faalt, retourneer lege array
    node.warn('Sales orders parse error: ' + e.message);
    msg.payload = [];
}

// CORS headers
msg.headers = {
    'Access-Control-Allow-Origin': '*',
    'Access-Control-Allow-Methods': 'GET, OPTIONS',
    'Content-Type': 'application/json'
};

return msg;

